        self.몸 = turtle.Turtle()
        self.몸.shape("square")
        self.몸.color("purple")
        self.몸.penup()
        self.처음으로()
    def 처음으로(self):
        self.줄 = self.처음줄
        self.칸 = self.처음칸
        self.보이기()
    def 보이기(self):
        self.몸.goto(가로(self.칸), 세로(self.줄))
    def 다가가기(self, 상대):
        if 상대.칸 > self.칸 and 지도[self.줄][self.칸 + 1] != "#":
            self.칸 = self.칸 + 1
        elif 상대.칸 < self.칸 and 지도[self.줄][self.칸 - 1] != "#":
            self.칸 = self.칸 - 1
        elif 상대.줄 > self.줄 and 지도[self.줄 + 1][self.칸] != "#":
            self.줄 = self.줄 + 1
        elif 상대.줄 < self.줄 and 지도[self.줄 - 1][self.칸] != "#":
            self.줄 = self.줄 - 1
        self.보이기()

유령들 = []

def 지도그리기():
    붓.clear()
    for 하나 in 유령들:
        하나.몸.hideturtle()
    유령들.clear()
    for 줄 in range(len(지도)):
        for 칸 in range(len(지도[줄])):
            글자 = 지도[줄][칸]
            if 글자 in 색들:
                칸칠하기(줄, 칸, 색들[글자])
            elif 글자 == "*":
                보석들.append(보석(줄, 칸))
            elif 글자 == "G":
                유령들.append(유령(줄, 칸))

지도그리기()

처음수 = len(보석들)
목숨 = 3
판 = turtle.Turtle()
판.hideturtle()
판.penup()
판.goto(-210, 155)

def 판쓰기():
    판.clear()
    판.write("보석 " + str(처음수 - len(보석들)) + " / " + str(처음수) + "  목숨 " + str(목숨))

판쓰기()

class 탐험가:
    def __init__(self):
        self.몸 = turtle.Turtle()
        self.몸.shape("turtle")
        self.몸.color("blue")
        self.몸.penup()
        self.처음으로()
    def 처음으로(self):
        for 줄 in range(len(지도)):
            for 칸 in range(len(지도[줄])):
                if 지도[줄][칸] == "S":
                    self.줄 = 줄
                    self.칸 = 칸
        self.보이기()
    def 보이기(self):
        self.몸.goto(가로(self.칸), 세로(self.줄))
    def 가기(self, 위아래, 옆):
        if 지도[self.줄 + 위아래][self.칸 + 옆] != "#":
            self.줄 = self.줄 + 위아래
            self.칸 = self.칸 + 옆
            self.보이기()

나 = 탐험가()

def 위():
    나.가기(-1, 0)

def 아래():
    나.가기(1, 0)

def 왼쪽():
    나.가기(0, -1)

def 오른쪽():
    나.가기(0, 1)

turtle.onkeypress(위, "Up")
turtle.onkeypress(아래, "Down")
turtle.onkeypress(왼쪽, "Left")
turtle.onkeypress(오른쪽, "Right")
turtle.listen()

장면 = 0
while 목숨 > 0:
    장면 = 장면 + 1
    for 돌 in 보석들:
        if 돌.줄 == 나.줄 and 돌.칸 == 나.칸:
            돌.몸.hideturtle()
            보석들.remove(돌)
            판쓰기()
            break
    if 장면 % 8 == 0:
        for 하나 in 유령들:
            하나.다가가기(나)
    for 하나 in 유령들:
        if 하나.줄 == 나.줄 and 하나.칸 == 나.칸:
            목숨 = 목숨 - 1
            나.처음으로()
            하나.처음으로()
            판쓰기()
    if len(보석들) == 0 and 지도[나.줄][나.칸] == "E":
        판번호 = 판번호 + 1
        if 판번호 == len(지도들):
            판.clear()
            판.write("다 깼어요!")
            break
        지도 = 지도들[판번호]
        지도그리기()
        처음수 = len(보석들)
        판쓰기()
        나.처음으로()
    turtle.update()
    time.sleep(0.02)

if 목숨 == 0:
    판.clear()
    판.write("끝! 다시 해 봐요")
turtle.update()
